@startuml

class Patient {
  + name : string
}

class Family {
  + name : string
}

class Doctor {
  + name : string
}

class Appointment {
  + date : date
}

class Visit {
  + diagnosis : string
  + treatment : string
}

class Medication {
  + name : string
}

class Receptionist {}

class Nurse {}

class DoctorUser {}

class FamilyHead {}

Patient "0..*" -- "1" Family : belongs to
Family "1" -- "0..1" Doctor : has primary care physician
Patient "1" -- "0..*" Appointment : has
Patient "1" -- "0..*" Visit : has
Visit "1" -- "0..*" Medication : prescribes
Visit "0..*" -- "0..1" Doctor : seen by
Appointment "0..*" -- "1" Patient : scheduled for
Receptionist "1" -- "0..*" Appointment : schedules
Receptionist "1" -- "0..*" Patient : enters information
Nurse "1" -- "0..*" Visit : records
Nurse "1" -- "0..*" Medication : records
DoctorUser "1" -- "0..*" Visit : enters information
DoctorUser "1" -- "0..*" Medication : prescribes
DoctorUser "1" -- "0..*" Appointment : schedules
FamilyHead "1" -- "1" Family : heads

@enduml

